function restPanel6(){let a=S.active;if(!a)return '';let quota=ensureRestQuota6(a),stage=restStage6(a),reason=restBlocked6(a);return `<section class="panel"><h2>Восстановление на турнире</h2><p>Не более двух пакетов за группы и двух за плей-офф. Один пакет на серию, между картами. Отдых применяется к каждому игроку основы перед следующей картой. Усталость: ${metric('fatigue')}% · бюджет ${cash(S.budget)}.</p><p><b>Группы и отбор: ${quota.groups}/2 · Плей-офф: ${quota.playoffs}/2</b><br>Осталось на текущей стадии: ${2-quota[stage]}.</p>${btn('Восстановление −15 усталости · $15 000',"buyRest6('basic')",false,!!reason||S.budget<15000)} ${btn('Специальный отдых −30 · $40 000',"buyRest6('premium')",true,!!reason||S.budget<40000)}<p class="sub">${reason||'Время турнира не проматывается; оплата только игровой валютой.'}</p></section>`}
