modelView4=function(){return head('MATCH ENGINE / 6','Рейтинг, решения и восстановление','Победа через последовательные события на карте')+`<div class="columns"><section class="panel"><h2>Что влияет на матч</h2><p>Мастерство каждого игрока и рейтинг состава влияют на экономику и исполнение боёв. Энергия снижает эффективность уставших игроков. Пулы героев, предметы, уровень, стадия и готовность способностей также учитываются.</p><p>Приказы действуют 10 минут в пошаговом режиме и 3 минуты в лайве. Фарм полезнее в начале, оборона — при отставании, осада — с преимуществом и подготовкой. Ранний штурм или Рошан без команды повышают риск. Один и тот же приказ может помочь или навредить.</p></section><section class="panel"><h2>Правила экономики</h2><p>Изменение перевеса ограничено 600 золотыми в минуту: максимум 6000 за любые 10 минут. Награды за убийства и объекты поступают постепенно. График строится по фактической экономике героев.</p><p>При отставании от 10 000 команда не может разрушить Древнего в ближайшие 10 минут. Блокировка обновляется, пока сохраняется такое отставание. Победить можно только после последовательного сноса башен и открытия базы.</p><p>Эти ограничения — выбранные правила симулятора. В реальной Dota возможны более быстрые камбэки. Оценка позиции не является проверенной вероятностью.</p></section></div><section class="panel"><h2>Турниры</h2><p>У серий отдельные этапы и верхняя/нижняя сетки. В календаре указаны источник и ограничения конкретного шаблона. Неанонсированные выпуски используют выбранный регламент как сценарий карьеры.</p><p>Старый начатый турнир сохраняет свою сетку до завершения; новые форматы включаются со следующего турнира. Новая модель карты применяется и к текущему сохранению.</p></section>`};

const buyBase6=buyback4;buyback4=function(i){let m=S.active?.live,p=m?.sides[0].heroes[i];if(m?.modelVersion===6&&p&&p.deadUntil>m.clock){let cost=buybackCost4(p),now=net4(m.sides[0])-net4(m.sides[1]),old=m.goldTrail[0];if(now-cost<Math.max(...m.goldTrail.map(x=>x.gold))-6000){toast('Выкуп временно недоступен: лимит изменения экономики.');return}}buyBase6(i)};

